// @FIGURE_CODE_BEGIN
(function () {
  var SERIF = 'Georgia, "Times New Roman", serif';
  var DARK = '#3f6791';
  var PALE = '#c4d4e5';
  var ENV = '#dde7f2';
  var LINEB = '#7fa1c4';
  var INK = '#111111';

  var VW = 680, VH = 453;
  var X0 = 66;
  var BASE = 351;                       // pixels for L = 1
  var PANEL_Y = [123, 207, 291, 375];
  var AMP = 23;

  var st = { n: 1, L: 1, osc: false, highlight: false, phase: 1 };

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, VW, VH);
  var root = draw.group();
  var gWaves = root.group();
  var gStatic = root.group();

  function lenPx() { return BASE * st.L; }

  /* ---------- text helpers ---------- */
  function txt(g, s, x, y, o) {
    o = o || {};
    var t = g.plain(s);
    t.font({
      family: SERIF,
      size: o.size || 14,
      anchor: o.anchor || 'start',
      style: (o.italic === false) ? 'normal' : 'italic'
    });
    t.attr({ x: x, y: y, fill: o.fill || INK });
    if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
    return t;
  }
  function widthOf(t, fallbackChars, size) {
    var w = 0;
    try { w = t.node.getComputedTextLength(); } catch (e) { w = 0; }
    if (!w || !isFinite(w)) w = (fallbackChars || 2) * 0.55 * (size || 14);
    return w;
  }

  // items: {s:'text'} | {v:'λ', sub:'1'} | {f:['2','n']}, each may carry pre gap
  function drawExpr(g, items, x, y, fs) {
    var cx = x;
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      if (it.pre) cx += it.pre;
      if (it.f) {
        var nfs = fs * 0.78;
        var tn = txt(g, it.f[0], 0, 0, { size: nfs, anchor: 'middle' });
        var td = txt(g, it.f[1], 0, 0, { size: nfs, anchor: 'middle' });
        var w = Math.max(widthOf(tn, it.f[0].length, nfs), widthOf(td, it.f[1].length, nfs)) + 5;
        var mid = cx + w / 2;
        tn.attr({ x: mid, y: y - fs * 0.40 });
        td.attr({ x: mid, y: y + fs * 0.80 });
        g.line(cx + 1, y - fs * 0.25, cx + w - 1, y - fs * 0.25).stroke({ color: INK, width: 1 });
        cx += w + 2;
      } else if (it.v) {
        var tb = txt(g, it.v, cx, y, { size: fs });
        var wb = widthOf(tb, it.v.length, fs);
        var ts = txt(g, it.sub, cx + wb + 0.5, y + fs * 0.27, { size: fs * 0.68 });
        cx += wb + widthOf(ts, String(it.sub).length, fs * 0.68) + 1.5;
      } else {
        var t = txt(g, it.s, cx, y, { size: fs, italic: it.italic });
        cx += widthOf(t, it.s.length, fs);
      }
    }
    return cx;
  }

  /* ---------- geometry ---------- */
  function wavePts(n, len, cy, amp) {
    var pts = [], N = 170;
    for (var i = 0; i <= N; i++) {
      var t = i / N;
      pts.push([X0 + t * len, cy - amp * Math.sin(n * Math.PI * t)]);
    }
    return pts;
  }

  function arrowHead(g, x, y, dir, col) {
    g.polygon([[x, y], [x + dir * 9, y - 3.6], [x + dir * 9, y + 3.6]]).fill(col || INK);
  }
  function vArrow(g, x, yTop, yBot, col) {
    g.line(x, yTop + 4, x, yBot - 4).stroke({ color: col, width: 1, dasharray: '3,3' });
    g.polygon([[x, yTop], [x - 3, yTop + 6], [x + 3, yTop + 6]]).fill(col);
    g.polygon([[x, yBot], [x - 3, yBot - 6], [x + 3, yBot - 6]]).fill(col);
  }

  /* ---------- waves layer ---------- */
  function modeBody(n) {
    return 'Mode n = ' + n + ' fits ' + n + ' half-wavelength' + (n > 1 ? 's' : '') +
      ' between the two fixed ends, so (' + n + '/2)\u03BB = L and \u03BB = 2L/' + n + '. ' +
      'It carries ' + (n - 1) + ' interior node' + ((n - 1) === 1 ? '' : 's') +
      ' that never move and ' + n + ' antinode' + (n > 1 ? 's' : '') + ' of maximum swing.';
  }

  function drawWaves() {
    gWaves.clear();
    var len = lenPx();
    for (var i = 0; i < 4; i++) {
      var n = i + 1, cy = PANEL_Y[i];
      var active = (st.n === n);
      var op = (st.highlight && !active) ? 0.26 : 1;
      var g = gWaves.group().opacity(op);
      var ph = (active && st.osc) ? st.phase : 1;

      if (active && st.osc) {
        g.polyline(wavePts(n, len, cy, AMP)).fill('none').stroke({ color: ENV, width: 1.2 });
        g.polyline(wavePts(n, len, cy, -AMP)).fill('none').stroke({ color: ENV, width: 1.2 });
      }
      g.polyline(wavePts(n, len, cy, -AMP * ph)).fill('none')
        .stroke({ color: PALE, width: 2.2, linecap: 'round', linejoin: 'round' });
      g.polyline(wavePts(n, len, cy, AMP * ph)).fill('none')
        .stroke({ color: DARK, width: 2.2, linecap: 'round', linejoin: 'round' });

      g.circle(6.6).center(X0, cy).fill(INK);
      g.circle(6.6).center(X0 + len, cy).fill(INK);

      if (st.highlight && active) {
        var k;
        for (k = 1; k < n; k++) {
          var xn = X0 + k * len / n;
          var c = g.circle(8).center(xn, cy).fill('#ffffff').stroke({ color: '#2f5d8f', width: 1.4 });
          c.css('cursor', 'pointer');
          (function (xx) {
            c.on('mousemove', function (e) { showTooltip('Node — displacement is always zero here', e); })
              .on('mouseleave', hideTooltip);
          })(xn);
        }
        for (k = 0; k < n; k++) {
          var xa = X0 + (k + 0.5) * len / n;
          vArrow(g, xa, cy - AMP - 8, cy + AMP + 8, '#9aa9b8');
        }
      }

      var hit = g.rect(len + 44, 76).move(X0 - 22, cy - 38).fill('#ffffff').opacity(0);
      hit.css('cursor', 'pointer');
      (function (nn) {
        hit.on('mousemove', function (e) {
          showTooltip('n = ' + nn + ': ' + nn + ' half-wavelength' + (nn > 1 ? 's' : '') +
            ' fit in L  \u2192  \u03BB = 2L/' + nn, e);
        }).on('mouseleave', hideTooltip)
          .on('click', function () {
            update_modeSelect('n=' + nn);
            showPopup('Mode n = ' + nn, modeBody(nn));
          });
      })(n);
    }
  }

  /* ---------- static layer ---------- */
  function drawStatic() {
    gStatic.clear();
    var len = lenPx(), x1 = X0 + len;

    /* dimension arrow */
    var gd = gStatic.group();
    var yd = 16, mid = (X0 + x1) / 2;
    gd.line(X0, 5, X0, 31).stroke({ color: INK, width: 1 });
    gd.line(x1, 5, x1, 31).stroke({ color: INK, width: 1 });
    gd.line(X0 + 1, yd, mid - 11, yd).stroke({ color: INK, width: 1 });
    gd.line(mid + 11, yd, x1 - 1, yd).stroke({ color: INK, width: 1 });
    arrowHead(gd, X0 + 1, yd, 1);
    arrowHead(gd, x1 - 1, yd, -1);
    txt(gd, 'L', mid, yd + 5.5, { size: 16, anchor: 'middle', halo: true });

    /* reference line + nodes */
    var gr = gStatic.group();
    gr.line(X0, 45, x1, 45).stroke({ color: LINEB, width: 1.6 });
    var d1 = gr.circle(6.6).center(X0, 45).fill(INK);
    var d2 = gr.circle(6.6).center(x1, 45).fill(INK);
    [d1, d2].forEach(function (d) {
      d.css('cursor', 'pointer');
      d.on('mousemove', function (e) { showTooltip('Fixed end: clamped, so it is always a node', e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Boundary condition',
            'The string is clamped at both ends, so the displacement there must be zero at all times. ' +
            'Only waves whose shape vanishes at both x = 0 and x = L can survive on the string.');
        });
    });
    txt(gr, 'Node', X0, 64, { size: 13.5, anchor: 'middle', italic: false });
    txt(gr, 'Node', x1, 64, { size: 13.5, anchor: 'middle', italic: false });

    /* per-mode labels and equations */
    var col1 = x1 + 22, col2 = x1 + 112, fs = 14;
    var fits = [
      [{ f: ['1', '2'] }, { v: '\u03BB', sub: '1', pre: 2 }, { s: '= L', pre: 5 }],
      [{ v: '\u03BB', sub: '2' }, { s: '= L', pre: 5 }],
      [{ f: ['3', '2'] }, { v: '\u03BB', sub: '3', pre: 2 }, { s: '= L', pre: 5 }],
      [{ f: ['4', '2'] }, { v: '\u03BB', sub: '4', pre: 2 }, { s: '= L', pre: 5 }]
    ];
    for (var i = 0; i < 4; i++) {
      var n = i + 1, cy = PANEL_Y[i];
      var active = (st.n === n);
      var g = gStatic.group().opacity((st.highlight && !active) ? 0.26 : 1);
      txt(g, 'n = ' + n, 8, cy + 5, { size: 15 });
      drawExpr(g, fits[i], col1, cy + 5, fs);
      drawExpr(g, [
        { v: '\u03BB', sub: String(n) }, { s: '=', pre: 6 },
        { f: ['2', String(n)], pre: 6 }, { s: 'L', pre: 4 }
      ], col2, cy + 5, fs);
    }

    /* general rule */
    var gg = gStatic.group();
    drawExpr(gg, [
      { v: '\u03BB', sub: 'n' }, { s: '=', pre: 6 }, { f: ['2', 'n'], pre: 6 }, { s: 'L', pre: 4 }
    ], x1 + 38, 432, fs);
    txt(gg, 'n = 1, 2, 3, . . .', x1 + 123, 432, { size: fs });
    var ghit = gg.rect(190, 34).move(x1 + 30, 414).fill('#fff').opacity(0).css('cursor', 'pointer');
    ghit.on('mousemove', function (e) { showTooltip('The quantization rule: \u03BB\u2099 = 2L/n', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('\u03BB\u2099 = 2L / n',
          'Fitting exactly n half-wavelengths between the fixed ends requires n(\u03BB/2) = L. ' +
          'Solving gives \u03BB\u2099 = 2L/n for n = 1, 2, 3, … — a discrete ladder of allowed wavelengths, ' +
          'not a continuum. This is quantization produced purely by the boundary conditions.');
      });
  }

  /* ---------- render ---------- */
  function render() {
    var x1 = X0 + lenPx();
    var designW = x1 + 215;
    var s = Math.min(1, VW / designW);
    var tx = Math.max(0, (VW - designW * s) / 2);
    var ty = (VH - VH * s) / 2;
    root.attr('transform', 'translate(' + tx.toFixed(2) + ',' + ty.toFixed(2) + ') scale(' + s.toFixed(4) + ')');
    drawWaves();
    drawStatic();
  }

  function updateReadout() {
    var el = document.getElementById('readout');
    if (!el) return;
    var lam = 2 * st.L / st.n;
    el.textContent = 'n = ' + st.n + ',  L = ' + st.L.toFixed(2) +
      '  \u2192  \u03BB = 2L/' + st.n + ' = ' + lam.toFixed(2) +
      '   ·   interior nodes: ' + (st.n - 1) + ', antinodes: ' + st.n;
  }

  function syncButtons() {
    for (var k = 1; k <= 4; k++) {
      var b = document.getElementById('mbtn' + k);
      if (b) b.className = (k === st.n) ? 'active' : '';
    }
    var sel = document.getElementById('modeSelectInput');
    if (sel) sel.value = 'n=' + st.n;
    var chk = document.getElementById('oscillateInput');
    if (chk) chk.checked = st.osc;
  }

  /* ---------- controls ---------- */
  window.update_modeSelect = function (v) {
    st.n = parseInt(String(v).replace(/[^0-9]/g, ''), 10) || 1;
    st.highlight = true;
    syncButtons(); render(); updateReadout();
  };
  window.toggle_oscillate = function (on) {
    st.osc = !!on;
    st.highlight = true;
    if (!st.osc) st.phase = 1;
    t0 = performance.now();
    render(); updateReadout();
  };
  window.update_lengthL = function (v) {
    st.L = +v;
    st.highlight = true;
    render(); updateReadout();
  };
  window.showInsight = function () {
    showPopup('Key insight',
      'Boundary conditions quantize the wave. Because both ends must be nodes, only wavelengths that fit ' +
      'a whole number of half-waves into L survive, giving \u03BB\u2099 = 2L/n. Stretching L stretches every ' +
      'allowed wavelength in proportion, but never changes how many half-waves a given mode contains.');
  };

  /* ---------- demo steps ---------- */
  var steps = [
    { title: 'The fixed string', narration: 'A string of length L is clamped at both ends; those clamped points can never move, so they are permanent nodes. Every allowed wave must start and end at zero displacement.', state: { n: 1, L: 1, osc: false } },
    { title: 'Fundamental: one half-wavelength', narration: 'The simplest fit is a single hump with no interior nodes: exactly half a wavelength spans L, so \u00BD\u03BB\u2081 = L and \u03BB\u2081 = 2L.', state: { n: 1, L: 1, osc: false } },
    { title: 'Watch it vibrate', narration: 'Playing the motion shows the string sweeping between the dark and pale curves. The endpoints stay pinned while the centre antinode moves the most.', state: { n: 1, L: 1, osc: true } },
    { title: 'Second harmonic', narration: 'Fit two half-wavelengths and a node appears at the midpoint. Now \u03BB\u2082 = L \u2014 half the fundamental wavelength on the same string.', state: { n: 2, L: 1, osc: true } },
    { title: 'Third and fourth harmonics', narration: 'Three and then four half-wavelengths fit, giving two and three interior nodes and wavelengths 2L/3 and 2L/4. Only whole numbers of half-wavelengths are permitted.', state: { n: 4, L: 1, osc: true } },
    { title: 'Stretch the string', narration: 'Dragging L longer stretches every mode\u2019s wavelength in proportion while the number of nodes stays fixed, confirming \u03BB\u2099 = 2L/n.', state: { n: 3, L: 1.8, osc: true } }
  ];
  var cur = 0;

  function applyStep(i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    var s = steps[cur].state;
    st.n = s.n; st.L = s.L; st.osc = s.osc;
    st.highlight = (cur > 0);
    if (!st.osc) st.phase = 1;
    t0 = performance.now();
    var sl = document.getElementById('lengthLInput');
    if (sl) sl.value = String(s.L);
    var so = document.getElementById('lengthLVal');
    if (so) so.value = s.L.toFixed(2);
    syncButtons();
    document.getElementById('demoNarration').textContent = steps[cur].narration;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length + '  ·  ' + steps[cur].title;
    render(); updateReadout();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  /* ---------- animation ---------- */
  var t0 = performance.now();
  function loop(now) {
    if (st.osc) {
      st.phase = Math.cos(2 * Math.PI * 0.45 * (now - t0) / 1000);
      drawWaves();
    }
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  applyStep(0);
  window.__markRendered();
})();
